void secp256r1_mult_iss(const uint32_t in[16], uint32_t out[16]) {
    for (int i = 0; i < 16; ++i) {
        out[i] = 0;
    }
    for (int i = 0; i < 8; ++i) {
        uint64_t carry = 0;
        for (int j = 0; j < 8; ++j) {
            uint64_t prod = (uint64_t)in[i] * in[8 + j] + out[i + j] + carry;
            out[i + j] = (uint32_t)prod;
            carry = prod >> 32;
        }
        out[i + 8] = (uint32_t)carry;
    }
}
